package com.bookofthedeadnotifier;

import net.runelite.client.config.*;

import java.awt.*;

@ConfigGroup(BookOfTheDeadNotifierConfig.GROUP)
public interface BookOfTheDeadNotifierConfig extends Config
{
	String GROUP = "bookofthedeadreminder";

    @ConfigItem(
        keyName = "reminderStyle",
        name = "Reminder Text",
        description = "The style of reminder text to display",
        position = 0
    )
    default BookOfTheDeadNotifierStyle reminderStyle()
    {
        return BookOfTheDeadNotifierStyle.LONG_TEXT;
    }

    @ConfigItem(
        keyName = "notification",
        name = "Notification on Reminder",
        description = "Sends a notification when warning appears",
        position = 1
    )
    default Notification notification()
    {
        return Notification.ON;
    }

    @ConfigItem(
        keyName = "hideReminderHotkey",
        name = "Hide Reminder Hotkey",
        description = "Hotkey to dismiss the warning",
        position = 2
    )
    default Keybind hideReminderHotkey()
    {
        return Keybind.NOT_SET;
    }

    @ConfigSection(
        name = "Notification Conditions",
        description = "Choose which conditions trigger a reminder",
        position = 3,
        closedByDefault = true
    )
    String notificationConditionsSection = "notificationConditions";

    @ConfigItem(
        keyName = "notifyOnMissingBook",
        name = "Notify on Missing Book",
        description = "Show reminder when Book of the Dead is missing",
        position = 0,
        section = notificationConditionsSection
    )
    default boolean notifyOnMissingBook()
    {
        return true;
    }

    @ConfigItem(
        keyName = "notifyOnMissingRunes",
        name = "Notify on Missing Runes",
        description = "Show reminder when thrall runes are missing",
        position = 1,
        section = notificationConditionsSection
    )
    default boolean notifyOnMissingRunes()
    {
        return true;
    }

    @ConfigItem(
        keyName = "notifyOnWrongSpellbook",
        name = "Notify on Wrong Spellbook",
        description = "Show reminder when not on Arceuus spellbook",
        position = 2,
        section = notificationConditionsSection
    )
    default boolean notifyOnWrongSpellbook()
    {
        return true;
    }

    @ConfigSection(
        name = "Thrall Spell",
        description = "Which thrall you cast and when to warn about runes",
        position = 4,
        closedByDefault = true
    )
    String thrallSpellSection = "thrallSpell";

    @ConfigItem(
        keyName = "thrallTier",
        name = "Thrall Tier",
        description = "The thrall you cast; Auto uses the highest your Magic level allows",
        position = 0,
        section = thrallSpellSection
    )
    default ThrallTierSetting thrallTier()
    {
        return ThrallTierSetting.AUTO;
    }

    @Range(min = 1, max = 1000)
    @ConfigItem(
        keyName = "minCasts",
        name = "Minimum Casts",
        description = "Warn when you can cast fewer thralls than this",
        position = 1,
        section = thrallSpellSection
    )
    default int minCasts()
    {
        return 1;
    }

    @ConfigSection(
        name = "Display Options",
        description = "Customize the appearance of warnings",
        position = 5
    )
    String displaySection = "displayOptions";

    @ConfigItem(
        keyName = "customText",
        name = "Custom Text",
        description = "Custom text to display when using CUSTOM_TEXT style",
        position = 0,
        section = displaySection
    )
    default String customText()
    {
        return "Cannot cast thralls!";
    }

    @ConfigItem(
        keyName = "flashReminderBox",
        name = "Flash the Reminder Box",
        description = "Makes the reminder box flash between two colors",
        position = 1,
        section = displaySection
    )
    default boolean flashReminderBox()
    {
        return false;
    }

    @Alpha
    @ConfigItem(
        keyName = "reminderColor",
        name = "Color",
        description = "Main color for the reminder box",
        position = 2,
        section = displaySection
    )
    default Color reminderColor()
    {
        return new Color(255, 0, 0, 150);
    }

    @Alpha
    @ConfigItem(
        keyName = "flashColor",
        name = "Flash Color",
        description = "Secondary color to flash between (if flashing enabled)",
        position = 3,
        section = displaySection
    )
    default Color flashColor()
    {
        return new Color(70, 70, 70, 150);
    }

	@ConfigSection(
		name = "Feedback",
		description = "Suggestions, bug reports, and support",
		position = 99
	)
	String feedbackSection = "feedbackSection";

	@ConfigItem(
		keyName = "suggestButton",
		name = "Suggest a feature",
		description = "Have an idea or found a bug? Click the box to open the GitHub issues page",
		section = feedbackSection,
		position = 0
	)
	default boolean suggestButton()
	{
		return false;
	}

	@ConfigItem(
		keyName = "supportButton",
		name = "Buy me a coffee ❤",
		description = "Enjoying the plugin? Click the box to open the Ko-fi page",
		section = feedbackSection,
		position = 1
	)
	default boolean supportButton()
	{
		return false;
	}
}

package com.bookofthedeadnotifier;

import net.runelite.api.Client;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

import javax.inject.Inject;
import java.awt.*;

public class BookOfTheDeadNotifierOverlay extends OverlayPanel
{
    private final Client client;
    private final BookOfTheDeadNotifierPlugin plugin;
    private final BookOfTheDeadNotifierConfig config;

    @Inject
    private BookOfTheDeadNotifierOverlay(Client client, BookOfTheDeadNotifierPlugin plugin, BookOfTheDeadNotifierConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!shouldRenderWarning())
        {
            return null;
        }

        String displayText = getDisplayText();
        if (displayText == null)
        {
            return null;
        }

        setupPanelContent(displayText);
        configurePanelSize(graphics, displayText);
        configurePanelColor();

        return renderPanel(graphics);
    }

    private boolean shouldRenderWarning()
    {
        if (!plugin.shouldShowWarning())
        {
            return false;
        }

        MissingCondition condition = plugin.getCurrentMissingCondition();
        return condition != MissingCondition.NONE;
    }

    private void setupPanelContent(String displayText)
    {
        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(LineComponent.builder()
            .left(displayText)
            .build());
    }

    private void configurePanelSize(Graphics2D graphics, String displayText)
    {
        FontMetrics fontMetrics = graphics.getFontMetrics();
        int textWidth = fontMetrics.stringWidth(displayText);
        int padding = getTextPadding();
        int totalWidth = textWidth + padding;

        panelComponent.setPreferredSize(new Dimension(totalWidth, 0));
    }

    private void configurePanelColor()
    {
        Color backgroundColor = getCurrentBackgroundColor();
        panelComponent.setBackgroundColor(backgroundColor);
    }

    private Color getCurrentBackgroundColor()
    {
        if (shouldFlash())
        {
            return config.flashColor();
        }
        return config.reminderColor();
    }

    private boolean shouldFlash()
    {
        if (!config.flashReminderBox())
        {
            return false;
        }

        int gameCycle = client.getGameCycle();
        return gameCycle % 40 >= 20;
    }

    private Dimension renderPanel(Graphics2D graphics)
    {
        boolean useCustomTextStyle = config.reminderStyle() == BookOfTheDeadNotifierStyle.CUSTOM_TEXT;
        if (useCustomTextStyle)
        {
            return super.render(graphics);
        }
        return panelComponent.render(graphics);
    }

    private String getDisplayText()
    {
        BookOfTheDeadNotifierStyle style = config.reminderStyle();

        if (style == BookOfTheDeadNotifierStyle.CUSTOM_TEXT)
        {
            return config.customText();
        }

        if (style == BookOfTheDeadNotifierStyle.LONG_TEXT)
        {
            return plugin.getReminderLongText();
        }

        if (style == BookOfTheDeadNotifierStyle.SHORT_TEXT)
        {
            return plugin.getReminderShortText();
        }

        return null;
    }

    private int getTextPadding()
    {
        switch (config.reminderStyle())
        {
            case LONG_TEXT:
            case CUSTOM_TEXT:
                return -20;
            case SHORT_TEXT:
                return 10;
            default:
                return 0;
        }
    }
}

package com.bookofthedeadnotifier;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.LinkBrowser;

@Slf4j
@PluginDescriptor(
    name = "Book of the Dead Reminder",
    description = "Reminds you when you seem to be missing a thrall requirement (Book of the Dead, Arceuus spellbook, Thrall runes)",
    tags = {"jake", "arceuus", "thrall", "thralls", "book of the dead", "spell", "spellbook", "reminder", "necromancy", "resurrect", "ghost", "skeleton", "zombie", "rune", "runes", "lesser", "superior", "greater", "casts", "air", "earth", "fire", "mind", "death", "blood", "cosmic", "staff", "tome", "rune pouch"}
)
public class BookOfTheDeadNotifierPlugin extends Plugin
{
    private static final int ARCEUUS_SPELLBOOK = 3;
    private static final String SUGGEST_BUTTON_KEY = "suggestButton";
    private static final String SUPPORT_BUTTON_KEY = "supportButton";
    private static final String ISSUES_URL = "https://github.com/jakevollkommer/book-of-the-dead-reminder/issues";
    private static final String KO_FI_URL = "https://ko-fi.com/jakevollkommer";

    @Inject
    private Client client;

    @Inject
    private BookOfTheDeadNotifierConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private BookOfTheDeadNotifierOverlay overlay;

    @Inject
    private Notifier notifier;

    @Inject
    private KeyManager keyManager;

    @Inject
    private ClientThread clientThread;

    @Inject
    private PlayerLoadout loadout;

    private boolean hasArceuusSpellbook = false;
    private boolean hasSufficientThrallRunes = false;
    private boolean hasBookOfTheDead = false;
    private boolean warningShown = false;
    private MissingCondition currentMissingCondition = MissingCondition.NONE;
    private int castsAvailable = 0;
    private int magicLevel = 1;

    private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.hideReminderHotkey())
    {
        @Override
        public void hotkeyPressed()
        {
            hideWarning();
        }
    };

    @Override
    protected void startUp() throws Exception
    {
        overlayManager.add(overlay);
        keyManager.registerKeyListener(hotkeyListener);
        clientThread.invokeLater(this::refreshPlayerState);
        log.info("Book of the Dead Reminder started!");
    }

    @Override
    protected void shutDown() throws Exception
    {
        overlayManager.remove(overlay);
        keyManager.unregisterKeyListener(hotkeyListener);
        log.info("Book of the Dead Reminder stopped!");
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        if (event.getVarbitId() == VarbitID.SPELLBOOK || PlayerLoadout.isRunePouchVarbit(event.getVarbitId()))
        {
            refreshPlayerState();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            refreshPlayerState();
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (isInventoryOrEquipment(event.getContainerId()))
        {
            refreshPlayerState();
        }
    }

    // Magic experience arrives constantly in combat, so only a level change can move the auto tier.
    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        boolean magicLevelChanged = event.getSkill() == Skill.MAGIC && event.getLevel() != magicLevel;
        if (magicLevelChanged)
        {
            refreshPlayerState();
        }
    }

    // The config panel cannot host real buttons, so the Feedback "buttons" are checkboxes
    // that act as buttons: any click of the box, tick or untick, opens the link.
    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!BookOfTheDeadNotifierConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }

        if (openFeedbackLink(event))
        {
            return;
        }

        clientThread.invokeLater(this::refreshPlayerState);
    }

    private boolean openFeedbackLink(ConfigChanged event)
    {
        if (event.getNewValue() == null)
        {
            return false;
        }

        if (SUGGEST_BUTTON_KEY.equals(event.getKey()))
        {
            LinkBrowser.browse(ISSUES_URL);
            return true;
        }

        if (SUPPORT_BUTTON_KEY.equals(event.getKey()))
        {
            LinkBrowser.browse(KO_FI_URL);
            return true;
        }

        return false;
    }

    private void refreshPlayerState()
    {
        magicLevel = client.getRealSkillLevel(Skill.MAGIC);
        checkSpellbook();
        checkThrallRunes();
        checkBookOfTheDead();
        evaluateWarningState();
    }

    private boolean isInventoryOrEquipment(int containerId)
    {
        return containerId == InventoryID.INVENTORY.getId()
            || containerId == InventoryID.EQUIPMENT.getId();
    }

    private void checkSpellbook()
    {
        hasArceuusSpellbook = client.getVarbitValue(VarbitID.SPELLBOOK) == ARCEUUS_SPELLBOOK;
    }

    private void checkThrallRunes()
    {
        ThrallTier tier = config.thrallTier().resolve(magicLevel);
        castsAvailable = loadout.castsAvailable(tier);
        hasSufficientThrallRunes = castsAvailable >= config.minCasts();
    }

    private void checkBookOfTheDead()
    {
        hasBookOfTheDead = loadout.carries(ItemID.BOOK_OF_THE_DEAD);
    }

    private void evaluateWarningState()
    {
        boolean shouldWarn = countConditionsMet() == 2;

        if (shouldWarn)
        {
            handleWarningState();
        }
        else
        {
            hideWarning();
        }
    }

    private int countConditionsMet()
    {
        int count = 0;
        if (hasArceuusSpellbook) count++;
        if (hasSufficientThrallRunes) count++;
        if (hasBookOfTheDead) count++;
        return count;
    }

    private void handleWarningState()
    {
        MissingCondition missingCondition = determineMissingCondition();

        if (!isConditionNotificationEnabled(missingCondition))
        {
            hideWarning();
            return;
        }

        boolean conditionChanged = missingCondition != currentMissingCondition;

        if (conditionChanged)
        {
            currentMissingCondition = missingCondition;
            showWarning();
        }
    }

    private boolean isConditionNotificationEnabled(MissingCondition condition)
    {
        switch (condition)
        {
            case BOOK_OF_THE_DEAD:
                return config.notifyOnMissingBook();
            case THRALL_RUNES:
                return config.notifyOnMissingRunes();
            case ARCEUUS_SPELLBOOK:
                return config.notifyOnWrongSpellbook();
            default:
                return false;
        }
    }

    private MissingCondition determineMissingCondition()
    {
        if (!hasBookOfTheDead)
        {
            return MissingCondition.BOOK_OF_THE_DEAD;
        }

        if (!hasArceuusSpellbook)
        {
            return MissingCondition.ARCEUUS_SPELLBOOK;
        }

        if (!hasSufficientThrallRunes)
        {
            return MissingCondition.THRALL_RUNES;
        }

        return MissingCondition.NONE;
    }

    public MissingCondition getCurrentMissingCondition()
    {
        return currentMissingCondition;
    }

    public String getReminderLongText()
    {
        return isRunningLowOnRunes()
            ? "Low on thrall runes (" + describeCastsRemaining() + ")"
            : currentMissingCondition.getLongText();
    }

    public String getReminderShortText()
    {
        return isRunningLowOnRunes()
            ? describeCastsRemaining()
            : currentMissingCondition.getShortText();
    }

    // Below the configured minimum but not empty, so naming the shortfall beats "missing runes".
    private boolean isRunningLowOnRunes()
    {
        return currentMissingCondition == MissingCondition.THRALL_RUNES && castsAvailable > 0;
    }

    private String describeCastsRemaining()
    {
        return castsAvailable == 1 ? "1 cast" : castsAvailable + " casts";
    }

    private void showWarning()
    {
        boolean isFirstWarning = !warningShown;
        if (isFirstWarning)
        {
            warningShown = true;
            sendNotification();
        }
    }

    private void sendNotification()
    {
        if (!config.notification().isEnabled())
        {
            return;
        }

        notifier.notify(config.notification(), "Thrall Reminder: " + getReminderLongText());
    }

    private void hideWarning()
    {
        if (!warningShown)
        {
            return;
        }

        warningShown = false;
        currentMissingCondition = MissingCondition.NONE;
    }

    public boolean shouldShowWarning()
    {
        return warningShown;
    }

    @Provides
    BookOfTheDeadNotifierConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BookOfTheDeadNotifierConfig.class);
    }
}

package com.bookofthedeadnotifier;

public enum BookOfTheDeadNotifierStyle {
    LONG_TEXT,
    SHORT_TEXT,
    CUSTOM_TEXT
}

package com.bookofthedeadnotifier;

public enum MissingCondition
{
    BOOK_OF_THE_DEAD("Missing Book of the Dead", "Book!"),
    ARCEUUS_SPELLBOOK("Not on Arceuus spellbook", "Spellbook!"),
    THRALL_RUNES("Missing thrall runes", "Runes!"),
    NONE("", "");

    private final String longText;
    private final String shortText;

    MissingCondition(String longText, String shortText)
    {
        this.longText = longText;
        this.shortText = shortText;
    }

    public String getLongText()
    {
        return longText;
    }

    public String getShortText()
    {
        return shortText;
    }
}

package com.bookofthedeadnotifier;

import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Set;

/**
 * Reads what the player is carrying: worn equipment, inventory, and the runes stored in a rune
 * pouch. Every read must happen on the client thread.
 */
@Singleton
public class PlayerLoadout
{
	private static final int[] RUNE_POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1,
		VarbitID.RUNE_POUCH_TYPE_2,
		VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4,
		VarbitID.RUNE_POUCH_TYPE_5,
		VarbitID.RUNE_POUCH_TYPE_6
	};
	private static final int[] RUNE_POUCH_QUANTITY_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1,
		VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4,
		VarbitID.RUNE_POUCH_QUANTITY_5,
		VarbitID.RUNE_POUCH_QUANTITY_6
	};
	private static final Set<Integer> RUNE_POUCH_ITEM_IDS = Set.of(
		ItemID.BH_RUNE_POUCH,
		ItemID.BH_RUNE_POUCH_TROUVER,
		ItemID.DIVINE_RUNE_POUCH,
		ItemID.DIVINE_RUNE_POUCH_TROUVER);
	private static final EquipmentInventorySlot[] INFINITE_SOURCE_SLOTS = {
		EquipmentInventorySlot.WEAPON,
		EquipmentInventorySlot.SHIELD
	};
	private static final int UNLIMITED = Integer.MAX_VALUE;

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	public static boolean isRunePouchVarbit(int varbitId)
	{
		return contains(RUNE_POUCH_TYPE_VARBITS, varbitId) || contains(RUNE_POUCH_QUANTITY_VARBITS, varbitId);
	}

	/**
	 * How many thralls of the given tier the player can currently cast.
	 */
	public int castsAvailable(ThrallTier tier)
	{
		// Resolved once per check rather than per rune: finding the pouch means scanning both
		// containers for each of its four item ids.
		boolean carriesRunePouch = carriesRunePouch();
		return tier.castsAvailable(rune -> availableRunes(rune, carriesRunePouch));
	}

	public boolean carries(int itemId)
	{
		return contains(InventoryID.EQUIPMENT, itemId) || contains(InventoryID.INVENTORY, itemId);
	}

	private int availableRunes(ThrallRune rune, boolean carriesRunePouch)
	{
		if (hasInfiniteSourceEquipped(rune))
		{
			return UNLIMITED;
		}

		int carried = countInInventory(rune);
		return carriesRunePouch ? carried + countInRunePouch(rune) : carried;
	}

	private boolean hasInfiniteSourceEquipped(ThrallRune rune)
	{
		if (!rune.hasInfiniteSources())
		{
			return false;
		}

		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return false;
		}

		for (EquipmentInventorySlot slot : INFINITE_SOURCE_SLOTS)
		{
			Item item = equipment.getItem(slot.getSlotIdx());
			if (item != null && rune.isInfiniteSource(itemManager.canonicalize(item.getId())))
			{
				return true;
			}
		}

		return false;
	}

	private int countInInventory(ThrallRune rune)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		if (inventory == null)
		{
			return 0;
		}

		int count = 0;
		for (Item item : inventory.getItems())
		{
			if (rune.isSatisfiedByRune(item.getId()))
			{
				count += item.getQuantity();
			}
		}
		return count;
	}

	private int countInRunePouch(ThrallRune rune)
	{
		int count = 0;
		for (int slot = 0; slot < RUNE_POUCH_TYPE_VARBITS.length; slot++)
		{
			count += countInRunePouchSlot(slot, rune);
		}
		return count;
	}

	private int countInRunePouchSlot(int slot, ThrallRune rune)
	{
		int runeEnumId = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[slot]);
		int quantity = client.getVarbitValue(RUNE_POUCH_QUANTITY_VARBITS[slot]);

		if (runeEnumId == 0 || quantity <= 0)
		{
			return 0;
		}

		return rune.isSatisfiedByRune(runePouchItemId(runeEnumId)) ? quantity : 0;
	}

	private int runePouchItemId(int runeEnumId)
	{
		EnumComposition runePouchRunes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		return runePouchRunes == null ? 0 : runePouchRunes.getIntValue(runeEnumId);
	}

	private boolean carriesRunePouch()
	{
		return RUNE_POUCH_ITEM_IDS.stream().anyMatch(this::carries);
	}

	private boolean contains(InventoryID containerId, int itemId)
	{
		ItemContainer container = client.getItemContainer(containerId);
		if (container == null)
		{
			return false;
		}

		for (Item item : container.getItems())
		{
			if (itemManager.canonicalize(item.getId()) == itemId)
			{
				return true;
			}
		}
		return false;
	}

	private static boolean contains(int[] values, int value)
	{
		for (int candidate : values)
		{
			if (candidate == value)
			{
				return true;
			}
		}
		return false;
	}
}

package com.bookofthedeadnotifier;

import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.ToIntFunction;

/**
 * A tier of Resurrect Thrall spells. Ghost, skeleton and zombie thralls of the same tier share a
 * Magic requirement and a rune cost, so the tier alone determines what the player needs to carry.
 */
public enum ThrallTier
{
	LESSER("Lesser", 38, ThrallRune.AIR, ThrallRune.MIND),
	SUPERIOR("Superior", 57, ThrallRune.EARTH, ThrallRune.DEATH),
	GREATER("Greater", 76, ThrallRune.FIRE, ThrallRune.BLOOD);

	private static final class RunesPerCast
	{
		private static final int ELEMENTAL = 10;
		private static final int CATALYTIC = 5;
		private static final int COSMIC = 1;
	}

	private final String displayName;
	private final int magicLevel;
	private final Map<ThrallRune, Integer> runesPerCast;

	ThrallTier(String displayName, int magicLevel, ThrallRune elemental, ThrallRune catalytic)
	{
		this.displayName = displayName;
		this.magicLevel = magicLevel;

		Map<ThrallRune, Integer> costs = new EnumMap<>(ThrallRune.class);
		costs.put(elemental, RunesPerCast.ELEMENTAL);
		costs.put(catalytic, RunesPerCast.CATALYTIC);
		costs.put(ThrallRune.COSMIC, RunesPerCast.COSMIC);
		this.runesPerCast = Collections.unmodifiableMap(costs);
	}

	public int getMagicLevel()
	{
		return magicLevel;
	}

	public Map<ThrallRune, Integer> getRunesPerCast()
	{
		return runesPerCast;
	}

	/**
	 * How many thralls of this tier the given rune supply covers, limited by whichever rune runs
	 * out first.
	 */
	public int castsAvailable(ToIntFunction<ThrallRune> availableRunes)
	{
		return runesPerCast.entrySet().stream()
			.mapToInt(cost -> availableRunes.applyAsInt(cost.getKey()) / cost.getValue())
			.min()
			.orElse(0);
	}

	/**
	 * The best tier the given Magic level can cast, falling back to the cheapest tier below the
	 * level requirement of every thrall spell.
	 */
	public static ThrallTier highestCastableAt(int magicLevel)
	{
		return Arrays.stream(values())
			.filter(tier -> magicLevel >= tier.magicLevel)
			.max(Comparator.comparingInt(ThrallTier::getMagicLevel))
			.orElse(LESSER);
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.bookofthedeadnotifier;

/**
 * The configured thrall tier, which may defer the choice to the player's Magic level.
 */
public enum ThrallTierSetting
{
	AUTO("Auto (by Magic level)", null),
	LESSER("Lesser", ThrallTier.LESSER),
	SUPERIOR("Superior", ThrallTier.SUPERIOR),
	GREATER("Greater", ThrallTier.GREATER);

	private final String displayName;
	private final ThrallTier tier;

	ThrallTierSetting(String displayName, ThrallTier tier)
	{
		this.displayName = displayName;
		this.tier = tier;
	}

	public ThrallTier resolve(int magicLevel)
	{
		return tier == null ? ThrallTier.highestCastableAt(magicLevel) : tier;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

